import json
import requests

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema import Data


class UpdateTaskToolComponent(Component):

    display_name = "Update Task Tool"
    description = (
        "Updates an existing task in the backend and returns "
        "the updated task id and status."
    )

    icon = "edit"

    name = "UpdateTaskTool"

    inputs = [

        MessageTextInput(
            name="task_id",
            display_name="Task Id",
            tool_mode=True,
        ),

        MessageTextInput(
            name="title",
            display_name="Task Title",
            tool_mode=True,
        ),

        MessageTextInput(
            name="due_date",
            display_name="Due Date",
            tool_mode=True,
        ),

        MessageTextInput(
            name="category",
            display_name="Category",
            tool_mode=True,
        ),

        MessageTextInput(
            name="task_priority",
            display_name="Priority",
            tool_mode=True,
        ),

        MessageTextInput(
            name="task_status",
            display_name="Status",
            tool_mode=True,
        ),

        MessageTextInput(
            name="source_type",
            display_name="Source Type",
            value="voice",
            tool_mode=True,
        ),

        MessageTextInput(
            name="access_token",
            display_name="Access Token",
            tool_mode=True,
        ),
    ]

    outputs = [
        Output(
            display_name="Result",
            name="output",
            method="update_task",
        )
    ]

    def _format_due_date(self):

        if not self.due_date:
            return None

        due = self.due_date.strip()

        if not due:
            return None

        if len(due) == 10:
            return f"{due}T00:00:00.000Z"

        return due

    def update_task(self) -> Data:
        
        # return Data(
        #         value=json.dumps({
        #             "title": self.title,
        #             "due_date": self.due_date,
        #             "category": self.category,
        #             "priority": self.task_priority,
        #             "task_status": self.task_status,
        #             "source_type": self.source_type,
        #             "Authorization": f"Bearer {self.access_token}"
        #         }, indent=2)
        #     )

        payload = {
            "title": self.title,
            "dueDate": self._format_due_date(),
            "category": self.category,
            "priority": self.task_priority,
            "status": self.task_status,
            "sourceType": self.source_type,
        }

        try:

            response = requests.put(
                f"https://localhost:7276/api/UserTasks/{self.task_id}",
                json=payload,
                headers={
                    "Content-Type": "application/json",
                    "Authorization": f"Bearer {self.access_token}"
                },
                verify=False,
                timeout=30,
            )

            response.raise_for_status()

            if response.status_code == 204:
                result = {
                    "success": True,
                    "taskId": self.task_id,
                    "status": self.task_status
                }
            else:
                backend = response.json()
            
                result = {
                    "success": True,
                    "taskId": backend.get("task", {}).get("id"),
                    "status": backend.get("task", {}).get("status")
                }

        except requests.HTTPError:

            try:
                error = response.json()
            except Exception:
                error = response.text

            result = {
                "success": False,
                "message": error
            }

        except Exception as ex:

            result = {
                "success": False,
                "message": str(ex),
                "request": payload,
            }

        return Data(value=json.dumps(result))
